// This file is generated by AI.

// 配音缓存与引用管理。
//
// 缓存音频只由内容哈希寻址; 「移除」只清 `-vocal=`, 从不删文件。
// 因此这里是**唯一**会删除音频的地方, 并且先扫描项目中真实的 `-vocal=` 引用,
// 把"未被任何场景引用"的文件列给用户确认后再删。

import { Button, Checkbox, Spinner } from '@fluentui/react-components';
import { ArrowSyncRegular, DeleteRegular } from '@fluentui/react-icons';
import { useEffect, useMemo, useState } from 'react';

import { voiceScanReferences, type CacheEntry, type VocalReference } from '../commands/voice';
import { AppDialog } from '../components/AppDialog';
import { useAppStore } from '../state/store';
import { voiceController } from './controller';

interface Props {
  open: boolean;
  onClose: () => void;
}

export function VoiceCacheDialog({ open, onClose }: Props) {
  const cache = useAppStore((state) => state.voiceCache);
  const projectPath = useAppStore((state) => state.projectPath);
  const [references, setReferences] = useState<VocalReference[] | null>(null);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);

  useEffect(() => {
    if (open) {
      void rescan();
      setSelected(new Set());
      setMessage(null);
    }
  }, [open]);

  const rescan = async () => {
    if (!projectPath) {
      setReferences([]);
      return;
    }
    setBusy(true);
    setError(null);
    try {
      setReferences(await voiceScanReferences(projectPath));
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : String(caught));
    } finally {
      setBusy(false);
    }
  };

  /** 项目中被引用的音频绝对路径集合 */
  const referencedPaths = useMemo(() => {
    const set = new Set<string>();
    for (const reference of references ?? []) set.add(normalize(reference.path));
    return set;
  }, [references]);

  const orphans = useMemo(
    () => cache.filter((entry) => !referencedPaths.has(normalize(entry.path))),
    [cache, referencedPaths]
  );

  const missing = useMemo(() => (references ?? []).filter((reference) => !reference.exists), [references]);

  if (!open) return null;

  const toggle = (hash: string) => {
    const next = new Set(selected);
    if (next.has(hash)) next.delete(hash);
    else next.add(hash);
    setSelected(next);
  };

  const purge = async () => {
    if (selected.size === 0) return;
    setBusy(true);
    try {
      await voiceController.clearCache([...selected]);
      setSelected(new Set());
      setMessage(`已删除 ${selected.size} 个缓存文件`);
      await rescan();
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : String(caught));
    } finally {
      setBusy(false);
    }
  };

  const totalSize = cache.reduce((sum, entry) => sum + entry.size, 0);
  const orphanSize = orphans.reduce((sum, entry) => sum + entry.size, 0);

  return (
    <AppDialog
      title="配音缓存与引用"
      description="缓存音频只由内容哈希寻址；删除缓存只影响历史记录的试听，已应用的音频位于项目内，不受影响。"
      size="large"
      height={600}
      compact
      onClose={onClose}
      footer={
        <Button appearance="secondary" onClick={onClose}>
          关闭
        </Button>
      }
    >
      <div className="dialog-toolbar">
        <Button size="small" appearance="subtle" icon={<ArrowSyncRegular />} onClick={() => void rescan()}>
          重新扫描项目引用
        </Button>
        {busy && <Spinner size="extra-tiny" />}
        <span className="dialog-toolbar-grow" />
        <Button
          size="small"
          appearance="secondary"
          disabled={orphans.length === 0}
          onClick={() => setSelected(new Set(orphans.map((entry) => entry.hash)))}
        >
          全选未引用
        </Button>
        <Button
          size="small"
          appearance="primary"
          icon={<DeleteRegular />}
          disabled={selected.size === 0}
          onClick={() => void purge()}
        >
          删除选中（{selected.size}）
        </Button>
      </div>

      <p className="voice-dialog-hint">
        缓存共 {cache.length} 个文件（{formatSize(totalSize)}），其中未被任何场景引用 {orphans.length} 个（
        {formatSize(orphanSize)}）。
      </p>

      {error && <p className="voice-error">{error}</p>}
      {message && <p className="voice-dialog-hint">{message}</p>}

      {missing.length > 0 && (
        <div className="voice-warn-block">
          <strong>脚本引用了 {missing.length} 个不存在的音频文件：</strong>
          {missing.slice(0, 20).map((reference) => (
            <div key={`${reference.scene}:${reference.line}`} className="voice-warn-line">
              {reference.scene}:{reference.line + 1} → {reference.vocal}
            </div>
          ))}
        </div>
      )}

      <div className="cache-list dialog-scroll">
        {cache.length === 0 && <p className="voice-dialog-empty">缓存为空。</p>}
        {cache.map((entry) => {
          const orphan = !referencedPaths.has(normalize(entry.path));
          return (
            <div key={entry.hash} className={`cache-item${orphan ? ' orphan' : ''}`}>
              <Checkbox checked={selected.has(entry.hash)} onChange={() => toggle(entry.hash)} />
              <span className="cache-hash">{entry.hash}</span>
              <span className="cache-size">{formatSize(entry.size)}</span>
              <span className="cache-flag">{orphan ? '未被引用' : '已引用'}</span>
            </div>
          );
        })}
      </div>
    </AppDialog>
  );
}

/** 路径归一化: 大小写与分隔符在 Windows 下不敏感 */
function normalize(path: string): string {
  return path.replace(/\//g, '\\').toLowerCase();
}

function formatSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(0)} KB`;
  return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
}

/** 兼容导出 (旧命名) */
export type { CacheEntry };
